const fmt=n=>new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(n);const percent=n=>new Intl.NumberFormat('es-CO',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n)+' %';
const city=document.querySelector('#city'),max=document.querySelector('#max'),sort=document.querySelector('#sort'),only=document.querySelector('#only'),list=document.querySelector('#list'),count=document.querySelector('#count');
function render(){let rows=data.filter(x=>(!city.value||x.city===city.value)&&x.price<=+max.value&&(!only.checked||x.rent!==null));rows.sort((a,b)=>sort.value==='price'?a.price-b.price:sort.value==='yield'?(b.rent?b.rent*12/b.price:-1)-(a.rent?a.rent*12/a.price:-1):a.rank-b.rank); count.textContent=rows.length+' inmuebles en selección';document.querySelector('#empty').hidden=!!rows.length;list.innerHTML=rows.map(x=>`<article class="listing-row"><div class="main-cell"><h3>${x.name}</h3><p>${x.city} · ${x.detail}</p><span class="badge ${x.rent===null?'pending':''}">${x.rent===null?'POR INVESTIGAR':x.rent>800000?'ESCENARIO A VALIDAR':'BAJO LA META'}</span></div><div><div class="money">${fmt(x.price)}</div><small>Precio anunciado</small></div><div><div class="rental ${x.rent===null?'not-yet':''}">${x.rent?fmt(x.rent)+'/mes':'Sin referencia'}</div><small>${x.rent?'Escenario, no oferta del inmueble':'Renta pendiente'}</small>${x.comp?`<br><a class="source" href="${x.comp}" target="_blank" rel="noopener">Ver comparable ↗</a>`:''}</div><div class="yield-cell"><div class="pct">${x.rent?percent(x.rent*12/x.price*100):'—'}</div><small>${x.note}</small></div><a class="arrow" href="${x.source}" target="_blank" rel="noopener" aria-label="Ver anuncio de ${x.name}">↗</a></article>`).join('')}
[city,max,sort,only].forEach(el=>el.addEventListener('change',render));render();
function calculate(){const p=RadarWizard.parsePesos(document.querySelector('#priceInput').value)||0,r=RadarWizard.parsePesos(document.querySelector('#rentInput').value)||0;document.querySelector('#yieldOutput').textContent=p>0&&r>=0?percent(r*12/p*100):'—';document.querySelector('#annualOutput').textContent=p>0&&r>=0?fmt(r*12):'—'}document.querySelectorAll('.calc-inputs input').forEach(el=>el.addEventListener('input',calculate));calculate();
const searchForm=document.querySelector('#marketSearch');const queryInput=document.querySelector('#query');const searchError=document.querySelector('#searchError');
document.querySelectorAll('.chips button').forEach(button=>button.addEventListener('click',()=>{queryInput.value=button.dataset.query;document.querySelectorAll('.chips button').forEach(b=>b.classList.toggle('active',b===button));queryInput.focus();}));
searchForm.addEventListener('submit',event=>{event.preventDefault();try{const url=buildSearchUrl({query:queryInput.value,location:document.querySelector('#place').value,min:document.querySelector('#minimum').value,max:document.querySelector('#maximum').value});searchError.hidden=true;window.open(url,'_blank','noopener,noreferrer');}catch(error){searchError.textContent=error.message;searchError.hidden=false;}});
